-- Hand-written: what the schema language cannot say (ERD §15 rules 53 to 57).

-- Rule 53 (R-404): one open request, awaiting the student's name or pending, per enrollment.
CREATE UNIQUE INDEX "ijazah_requests_one_open_per_enrollment_key" ON "ijazah_requests"("enrollment_id")
    WHERE "status" IN ('awaiting_student_name', 'pending');

-- Rule 54: a rejection names its reason; the decider and the instant are set together, on approve
-- or reject and only then.
ALTER TABLE "ijazah_requests" ADD CONSTRAINT "ijazah_requests_reason_check"
    CHECK ("status" <> 'rejected' OR ("reason" IS NOT NULL AND length(btrim("reason")) > 0));
ALTER TABLE "ijazah_requests" ADD CONSTRAINT "ijazah_requests_decided_check"
    CHECK (("decided_by_admin_id" IS NULL) = ("decided_at" IS NULL)
        AND ("decided_at" IS NOT NULL) = ("status" IN ('approved', 'rejected')));

-- Rule 55 (SRS DEC-72, FR-629): the sign-off's instant and administrator set together, never before
-- the rendering.
ALTER TABLE "ijazahs" ADD CONSTRAINT "ijazahs_signed_off_check"
    CHECK (("signed_off_at" IS NULL) = ("signed_off_by_admin_id" IS NULL)
        AND ("signed_off_at" IS NULL
            OR ("rendered_at" IS NOT NULL AND "signed_off_at" >= "rendered_at")));

-- Rule 56 (R-408): no report on oneself; a session report names its session, and a session or chat
-- report its enrollment; one open report per reporter, reported user and context.
ALTER TABLE "user_reports" ADD CONSTRAINT "user_reports_not_self_check"
    CHECK ("reporter_user_id" <> "reported_user_id");
ALTER TABLE "user_reports" ADD CONSTRAINT "user_reports_context_check"
    CHECK (("context" <> 'session' OR "session_id" IS NOT NULL)
        AND ("context" = 'profile' OR "enrollment_id" IS NOT NULL));
CREATE UNIQUE INDEX "user_reports_one_open_key"
    ON "user_reports"("reporter_user_id", "reported_user_id", "context") WHERE "status" = 'open';

-- Rule 57 (R-409): one open gender flag per user.
CREATE UNIQUE INDEX "gender_flags_one_open_per_user_key" ON "gender_flags"("flagged_user_id")
    WHERE "status" = 'open';
